CREATE TABLE `admins` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text NOT NULL,`password_hash` text NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `chk_admins_username` CHECK (length(trim(username)) BETWEEN 1 AND 100));
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE `admin_sessions` (`id` integer PRIMARY KEY AUTOINCREMENT,`admin_id` integer NOT NULL,`refresh_token_hash` text NOT NULL,`expires_at` datetime NOT NULL,`last_used_at` datetime,`created_at` datetime NOT NULL,CONSTRAINT `fk_admin_sessions_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_admin_sessions_token_hash` CHECK (length(refresh_token_hash) = 64));
CREATE TABLE `account_provider_links` (`web_account_id` integer PRIMARY KEY AUTOINCREMENT,`build_account_id` integer NOT NULL,`created_at` datetime NOT NULL,CONSTRAINT `fk_account_provider_links_web_account` FOREIGN KEY (`web_account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_account_provider_links_build_account` FOREIGN KEY (`build_account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_provider_links_distinct` CHECK (web_account_id <> build_account_id));
CREATE TABLE `account_quota_windows` (`account_id` integer,`mode` text NOT NULL,`remaining` integer NOT NULL,`total` integer NOT NULL,`usage_percent` real NOT NULL DEFAULT 0,`breakdown_json` text NOT NULL DEFAULT "[]",`window_seconds` integer NOT NULL,`reset_at` datetime,`synced_at` datetime,`source` text NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`account_id`,`mode`),CONSTRAINT `fk_account_quota_windows_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_quota_windows_mode` CHECK (length(trim(mode)) BETWEEN 1 AND 64),CONSTRAINT `chk_account_quota_windows_total` CHECK (total >= 0),CONSTRAINT `chk_account_quota_windows_breakdown` CHECK (length(breakdown_json) <= 8192),CONSTRAINT `chk_account_quota_windows_window` CHECK (window_seconds >= 0),CONSTRAINT `chk_account_quota_windows_source` CHECK (source IN ('default','estimated','upstream')),CONSTRAINT `chk_account_quota_windows_remaining` CHECK (remaining >= 0),CONSTRAINT `chk_account_quota_windows_usage_percent` CHECK (usage_percent >= 0 AND usage_percent <= 100));
CREATE TABLE `account_billing_snapshots` (`account_id` integer PRIMARY KEY AUTOINCREMENT,`plan_code` text,`plan_name` text,`monthly_limit` real NOT NULL DEFAULT 0,`used` real NOT NULL DEFAULT 0,`on_demand_cap` real NOT NULL DEFAULT 0,`on_demand_used` real NOT NULL DEFAULT 0,`prepaid_balance` real NOT NULL DEFAULT 0,`credit_usage_percent` real NOT NULL DEFAULT 0,`is_unified_billing_user` numeric NOT NULL DEFAULT false,`top_up_method` text,`usage_period_type` text,`usage_period_start` text,`usage_period_end` text,`billing_period_start` text,`billing_period_end` text,`history_json` text NOT NULL DEFAULT "[]",`synced_at` datetime NOT NULL, `on_demand_enabled` numeric,CONSTRAINT `fk_account_billing_snapshots_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_billing_usage_period_start` CHECK (length(usage_period_start) <= 64),CONSTRAINT `chk_billing_usage_period_end` CHECK (length(usage_period_end) <= 64),CONSTRAINT `chk_billing_monthly_limit` CHECK (monthly_limit >= 0),CONSTRAINT `chk_billing_plan_code` CHECK (length(plan_code) <= 100),CONSTRAINT `chk_billing_usage_period_type` CHECK (length(usage_period_type) <= 100),CONSTRAINT `chk_billing_on_demand_cap` CHECK (on_demand_cap >= 0),CONSTRAINT `chk_billing_top_up_method` CHECK (length(top_up_method) <= 100),CONSTRAINT `chk_billing_history_json_length` CHECK (length(history_json) <= 1048576),CONSTRAINT `chk_billing_credit_usage_percent` CHECK (credit_usage_percent >= 0),CONSTRAINT `chk_billing_on_demand_used` CHECK (on_demand_used >= 0),CONSTRAINT `chk_billing_plan_name` CHECK (length(plan_name) <= 160),CONSTRAINT `chk_billing_period_end` CHECK (length(billing_period_end) <= 64),CONSTRAINT `chk_billing_period_start` CHECK (length(billing_period_start) <= 64),CONSTRAINT `chk_billing_prepaid_balance` CHECK (prepaid_balance >= 0),CONSTRAINT `chk_billing_used` CHECK (used >= 0));
CREATE TABLE `account_quota_recovery` (`account_id` integer PRIMARY KEY AUTOINCREMENT,`kind` text NOT NULL,`status` text NOT NULL,`confirmed_used` integer NOT NULL DEFAULT 0,`confirmed_limit` integer NOT NULL DEFAULT 0,`exhausted_at` datetime,`next_probe_at` datetime,`last_confirmed_at` datetime,`updated_at` datetime NOT NULL,CONSTRAINT `fk_account_quota_recovery_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_quota_recovery_status` CHECK (status IN ('exhausted','probing')),CONSTRAINT `chk_quota_recovery_used` CHECK (confirmed_used >= 0),CONSTRAINT `chk_quota_recovery_limit` CHECK (confirmed_limit >= 0),CONSTRAINT `chk_quota_recovery_kind` CHECK (kind IN ('free','paid')));
CREATE TABLE `model_route_aliases` (`alias` text,`model_route_id` integer NOT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`alias`),CONSTRAINT `fk_model_route_aliases_model_route` FOREIGN KEY (`model_route_id`) REFERENCES `model_routes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_model_route_aliases_alias` CHECK (length(trim(alias)) BETWEEN 1 AND 255));
CREATE TABLE `model_route_accounts` (`model_route_id` integer,`account_id` integer,PRIMARY KEY (`model_route_id`,`account_id`),CONSTRAINT `fk_model_route_accounts_model_route` FOREIGN KEY (`model_route_id`) REFERENCES `model_routes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_model_route_accounts_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `account_model_capabilities` (`account_id` integer,`upstream_model` text NOT NULL,PRIMARY KEY (`account_id`,`upstream_model`),CONSTRAINT `fk_account_model_capabilities_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_model_capabilities_model` CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255));
CREATE TABLE `account_model_sync_states` (`account_id` integer PRIMARY KEY AUTOINCREMENT,`last_attempt_at` datetime NOT NULL,`last_success_at` datetime,`last_error` text,CONSTRAINT `fk_account_model_sync_states_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_model_sync_states_error` CHECK (length(last_error) <= 512));
CREATE TABLE `account_model_quota_blocks` (`account_id` integer,`upstream_model` text NOT NULL,`reason` text NOT NULL,`cooldown_until` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`account_id`,`upstream_model`),CONSTRAINT `fk_account_model_quota_blocks_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_model_quota_blocks_model` CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255),CONSTRAINT `chk_account_model_quota_blocks_reason` CHECK (length(trim(reason)) BETWEEN 1 AND 100));
CREATE TABLE `client_key_models` (`client_key_id` integer,`model_route_id` integer,PRIMARY KEY (`client_key_id`,`model_route_id`),CONSTRAINT `fk_client_key_models_client_key` FOREIGN KEY (`client_key_id`) REFERENCES `client_keys`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_client_key_models_model_route` FOREIGN KEY (`model_route_id`) REFERENCES `model_routes`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `billing_reservations` (`event_id` text,`client_key_id` integer NOT NULL,`amount` integer NOT NULL,`expires_at` datetime NOT NULL,`created_at` datetime NOT NULL,PRIMARY KEY (`event_id`),CONSTRAINT `fk_billing_reservations_client_key` FOREIGN KEY (`client_key_id`) REFERENCES `client_keys`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_billing_reservations_event_id` CHECK (length(event_id) BETWEEN 16 AND 64),CONSTRAINT `chk_billing_reservations_client_key_id` CHECK (client_key_id > 0),CONSTRAINT `chk_billing_reservations_amount` CHECK (amount > 0));
CREATE TABLE `web_response_states` (`response_id` text,`account_id` integer NOT NULL,`conversation_id` text NOT NULL,`upstream_parent_response_id` text NOT NULL,`response_json` text NOT NULL,`status` text NOT NULL,`expires_at` datetime NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`response_id`),CONSTRAINT `fk_web_response_states_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_web_response_states_account_id` CHECK (account_id > 0),CONSTRAINT `chk_web_response_states_conversation` CHECK (length(trim(conversation_id)) BETWEEN 1 AND 255),CONSTRAINT `chk_web_response_states_parent` CHECK (length(trim(upstream_parent_response_id)) BETWEEN 1 AND 255),CONSTRAINT `chk_web_response_states_expiry` CHECK (expires_at > created_at),CONSTRAINT `chk_web_response_states_id` CHECK (length(response_id) BETWEEN 1 AND 255),CONSTRAINT `chk_web_response_states_json` CHECK (length(response_json) <= 16777216),CONSTRAINT `chk_web_response_states_status` CHECK (status IN ('in_progress','completed','failed','cancelled')));
CREATE TABLE `runtime_settings` (`key` text,`value_json` text NOT NULL,`revision` integer NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`key`),CONSTRAINT `chk_runtime_settings_key` CHECK (length(trim(key)) BETWEEN 1 AND 64),CONSTRAINT `chk_runtime_settings_json_length` CHECK (length(value_json) <= 1048576));
CREATE TABLE `egress_operations_config` (`id` integer PRIMARY KEY AUTOINCREMENT,`probe_provider` text NOT NULL DEFAULT "cloudflare",`probe_interval_seconds` integer NOT NULL DEFAULT 900,`auto_assign_enabled` numeric NOT NULL DEFAULT false,`auto_balance_enabled` numeric NOT NULL DEFAULT false,`assignment_interval_seconds` integer NOT NULL DEFAULT 300,`build_fallback_mode` text NOT NULL DEFAULT "none",`build_fallback_node_id` integer NOT NULL DEFAULT 0,`web_fallback_mode` text NOT NULL DEFAULT "none",`web_fallback_node_id` integer NOT NULL DEFAULT 0,`console_fallback_mode` text NOT NULL DEFAULT "none",`console_fallback_node_id` integer NOT NULL DEFAULT 0,`web_asset_fallback_mode` text NOT NULL DEFAULT "none",`web_asset_fallback_node_id` integer NOT NULL DEFAULT 0,`updated_at` datetime NOT NULL, `console_asset_fallback_mode` text NOT NULL DEFAULT "none", `console_asset_fallback_node_id` integer NOT NULL DEFAULT 0, `subscription_proxy_migration_completed` numeric NOT NULL DEFAULT false, `proxy_profile_migration_completed` numeric NOT NULL DEFAULT false,CONSTRAINT `chk_egress_operations_config_id` CHECK (id = 1),CONSTRAINT `chk_egress_operations_config_probe_interval` CHECK (probe_interval_seconds BETWEEN 60 AND 86400),CONSTRAINT `chk_egress_operations_config_assignment_interval` CHECK (assignment_interval_seconds BETWEEN 60 AND 86400),CONSTRAINT `chk_egress_operations_config_probe_provider` CHECK (probe_provider IN ('ipinfo','cloudflare')));
CREATE TABLE IF NOT EXISTS "provider_accounts"  (`id` integer PRIMARY KEY AUTOINCREMENT,`identity_key` text NOT NULL,`provider` text NOT NULL,`name` text NOT NULL,`email` text,`user_id` text,`team_id` text,`source_key` text NOT NULL,`enabled` numeric NOT NULL,`auth_status` text NOT NULL,`priority` integer NOT NULL DEFAULT 1,`max_concurrent` integer NOT NULL DEFAULT 8,`minimum_remaining` real NOT NULL,`failure_count` integer NOT NULL,`cooldown_until` datetime,`last_error` text,`last_used_at` datetime,`observed_model` text,`observed_model_at` datetime,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`reauth_marked_at` datetime,`build_api_fallback` numeric NOT NULL DEFAULT false,`build_route_mode` text NOT NULL DEFAULT "auto",`build_super_entitled` numeric NOT NULL DEFAULT false,`egress_node_id` integer,`egress_assignment_mode` text NOT NULL DEFAULT "",`egress_assigned_at` datetime,CONSTRAINT `chk_accounts_name` CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT `chk_accounts_team_id` CHECK (length(team_id) <= 255),CONSTRAINT `chk_accounts_last_error` CHECK (length(last_error) <= 512),CONSTRAINT `chk_accounts_failure_count` CHECK (failure_count >= 0),CONSTRAINT `chk_accounts_minimum_remaining` CHECK (minimum_remaining >= 0),CONSTRAINT `chk_accounts_source_key` CHECK (length(trim(source_key)) BETWEEN 1 AND 512),CONSTRAINT `chk_accounts_auth_status` CHECK (auth_status IN ('active','reauthRequired')),CONSTRAINT `chk_accounts_observed_model` CHECK (length(observed_model) <= 255),CONSTRAINT `chk_accounts_identity_key` CHECK (length(identity_key) = 64),CONSTRAINT `chk_accounts_user_id` CHECK (length(user_id) <= 255),CONSTRAINT `chk_accounts_max_concurrent` CHECK (max_concurrent BETWEEN 1 AND 256),CONSTRAINT `chk_accounts_email` CHECK (length(email) <= 255),CONSTRAINT `chk_accounts_provider` CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT `fk_provider_accounts_egress_node` FOREIGN KEY (`egress_node_id`) REFERENCES `egress_nodes`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT `chk_accounts_build_route_mode` CHECK (build_route_mode IN ('auto','build','xai')),CONSTRAINT `chk_accounts_egress_assignment_mode` CHECK (egress_assignment_mode IN ('','manual','auto')));
CREATE TABLE `web_console_account_links` (`web_account_id` integer PRIMARY KEY AUTOINCREMENT,`console_account_id` integer NOT NULL,`created_at` datetime NOT NULL,CONSTRAINT `fk_web_console_account_links_web_account` FOREIGN KEY (`web_account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_web_console_account_links_console_account` FOREIGN KEY (`console_account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_web_console_account_links_distinct` CHECK (web_account_id <> console_account_id));
CREATE TABLE IF NOT EXISTS "web_account_profiles"  (`account_id` integer PRIMARY KEY AUTOINCREMENT,`tier` text NOT NULL,`synced_at` datetime,`nsfw_enabled_at` datetime,`terms_accepted_at` datetime,`terms_accepted_version` integer NOT NULL DEFAULT 0,`birth_date_set_at` datetime,`egress_identity` text NOT NULL DEFAULT "",CONSTRAINT `fk_provider_accounts_web_profile` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_web_account_profiles_tier` CHECK (tier IN ('auto','basic','super','heavy')),CONSTRAINT `chk_web_account_profiles_egress_identity` CHECK (length(egress_identity) <= 128));
CREATE TABLE `request_audit_attempts` (`id` integer PRIMARY KEY AUTOINCREMENT,`audit_id` integer NOT NULL,`number` integer NOT NULL,`source` text NOT NULL,`stage` text NOT NULL,`account_id` integer,`account_name` text NOT NULL DEFAULT "",`method` text NOT NULL DEFAULT "",`request_path` text NOT NULL DEFAULT "",`upstream_url` text NOT NULL DEFAULT "",`started_at` datetime NOT NULL,`duration_ms` integer NOT NULL DEFAULT 0,`upstream_status_code` integer,`upstream_status` text NOT NULL DEFAULT "",`response_headers_json` text NOT NULL DEFAULT "{}",`response_body` blob,`response_body_truncated` numeric NOT NULL DEFAULT false,`transport_error` text NOT NULL DEFAULT "",`error_chain_json` text NOT NULL DEFAULT "[]",CONSTRAINT `fk_request_audit_attempts_audit` FOREIGN KEY (`audit_id`) REFERENCES `request_audits`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_request_audit_attempts_duration` CHECK (duration_ms >= 0),CONSTRAINT `chk_request_audit_attempts_number` CHECK (number > 0),CONSTRAINT `chk_request_audit_attempts_source` CHECK (source IN ('upstream_http','gateway_transport','credential')),CONSTRAINT `chk_request_audit_attempts_method` CHECK (length(method) <= 16),CONSTRAINT `chk_request_audit_attempts_status_text` CHECK (length(upstream_status) <= 128),CONSTRAINT `chk_request_audit_attempts_status` CHECK (upstream_status_code IS NULL OR upstream_status_code BETWEEN 100 AND 599),CONSTRAINT `chk_request_audit_attempts_audit_id` CHECK (audit_id > 0),CONSTRAINT `chk_request_audit_attempts_body` CHECK (length(response_body) <= 65536),CONSTRAINT `chk_request_audit_attempts_upstream_url` CHECK (length(upstream_url) <= 4096),CONSTRAINT `chk_request_audit_attempts_headers` CHECK (length(response_headers_json) <= 32768),CONSTRAINT `chk_request_audit_attempts_account_name` CHECK (length(account_name) <= 160),CONSTRAINT `chk_request_audit_attempts_transport_error` CHECK (length(transport_error) <= 2048),CONSTRAINT `chk_request_audit_attempts_account_id` CHECK (account_id IS NULL OR account_id > 0),CONSTRAINT `chk_request_audit_attempts_stage` CHECK (length(trim(stage)) BETWEEN 1 AND 64),CONSTRAINT `chk_request_audit_attempts_error_chain` CHECK (length(error_chain_json) <= 32768),CONSTRAINT `chk_request_audit_attempts_request_path` CHECK (length(request_path) <= 2048));
CREATE TABLE IF NOT EXISTS "response_ownership"  (`response_id` text,`account_id` integer NOT NULL,`client_key_id` integer NOT NULL,`provider` text NOT NULL,`expires_at` datetime NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`model_route_id` integer NOT NULL DEFAULT 0,`prompt_cache_key` text NOT NULL DEFAULT "",`reasoning_replay_key` text NOT NULL DEFAULT "",PRIMARY KEY (`response_id`),CONSTRAINT `fk_response_ownership_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `fk_response_ownership_client_key` FOREIGN KEY (`client_key_id`) REFERENCES `client_keys`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_response_ownership_id` CHECK (length(response_id) BETWEEN 1 AND 255),CONSTRAINT `chk_response_ownership_provider` CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT `chk_response_ownership_expiry` CHECK (expires_at > created_at),CONSTRAINT `chk_response_ownership_cache_key` CHECK (length(prompt_cache_key) <= 64),CONSTRAINT `chk_response_ownership_replay_key` CHECK (length(reasoning_replay_key) <= 64));
CREATE TABLE `media_upload_tickets` (`token_hash` text,`asset_id` text NOT NULL,`job_id` text NOT NULL,`max_bytes` integer NOT NULL,`allowed_mime` text NOT NULL DEFAULT "video/mp4",`expires_at` datetime NOT NULL,`consumed_at` datetime,`created_at` datetime NOT NULL,PRIMARY KEY (`token_hash`),CONSTRAINT `chk_media_upload_tickets_token_hash` CHECK (length(token_hash) = 64),CONSTRAINT `chk_media_upload_tickets_job_id` CHECK (length(trim(job_id)) BETWEEN 1 AND 64),CONSTRAINT `chk_media_upload_tickets_max_bytes` CHECK (max_bytes > 0 AND max_bytes <= 268435456),CONSTRAINT `chk_media_upload_tickets_mime` CHECK (length(trim(allowed_mime)) BETWEEN 1 AND 128),CONSTRAINT `chk_media_upload_tickets_asset_id` CHECK (length(trim(asset_id)) BETWEEN 16 AND 64));
CREATE TABLE IF NOT EXISTS "media_assets"  (`id` text,`kind` text NOT NULL,`storage_key` text NOT NULL,`mime_type` text NOT NULL,`size_bytes` integer NOT NULL,`sha256` text NOT NULL,`created_at` datetime NOT NULL, `expires_at` datetime,PRIMARY KEY (`id`),CONSTRAINT `chk_media_assets_id` CHECK (length(trim(id)) BETWEEN 16 AND 64),CONSTRAINT `chk_media_assets_sha` CHECK (length(sha256) = 64),CONSTRAINT `chk_media_assets_storage_key` CHECK (length(trim(storage_key)) BETWEEN 1 AND 512),CONSTRAINT `chk_media_assets_kind` CHECK (kind IN ('image','video')),CONSTRAINT `chk_media_assets_mime` CHECK (mime_type IN ('image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime')),CONSTRAINT `chk_media_assets_size` CHECK (size_bytes > 0 AND size_bytes <= 268435456));
CREATE TABLE IF NOT EXISTS "client_keys"  (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`prefix` text NOT NULL,`secret_hash` text NOT NULL,`encrypted_secret` text NOT NULL,`enabled` numeric NOT NULL,`expires_at` datetime,`rpm_limit` integer NOT NULL DEFAULT 120,`max_concurrent` integer NOT NULL DEFAULT 8,`billing_limit_usd_ticks` integer NOT NULL DEFAULT 0,`billed_usage_usd_ticks` integer NOT NULL DEFAULT 0,`reserved_usage_usd_ticks` integer NOT NULL DEFAULT 0,`last_used_at` datetime,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`internal_kind` text,`allow_model_aliases` numeric NOT NULL DEFAULT false,`provider_scope_mask` integer NOT NULL DEFAULT 7,`tier_scope_mask` integer NOT NULL DEFAULT 7,CONSTRAINT `chk_client_keys_secret_hash` CHECK (length(secret_hash) = 64),CONSTRAINT `chk_client_keys_billed_usage` CHECK (billed_usage_usd_ticks >= 0),CONSTRAINT `chk_client_keys_billing_limit` CHECK (billing_limit_usd_ticks BETWEEN 0 AND 9000000000000000),CONSTRAINT `chk_client_keys_encrypted_secret` CHECK (length(trim(encrypted_secret)) BETWEEN 1 AND 4096),CONSTRAINT `chk_client_keys_prefix` CHECK (length(prefix) BETWEEN 1 AND 32),CONSTRAINT `chk_client_keys_reserved_usage` CHECK (reserved_usage_usd_ticks >= 0),CONSTRAINT `chk_client_keys_name` CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT `chk_client_keys_provider_scope` CHECK (provider_scope_mask BETWEEN 1 AND 7),CONSTRAINT `chk_client_keys_tier_scope` CHECK (tier_scope_mask IN (1,2,3,7)),CONSTRAINT `chk_client_keys_rpm` CHECK (rpm_limit BETWEEN 0 AND 100000),CONSTRAINT `chk_client_keys_max_concurrent` CHECK (max_concurrent BETWEEN 0 AND 1024));
CREATE TABLE IF NOT EXISTS "egress_subscription_sources"  (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`scope` text NOT NULL,`enabled` numeric NOT NULL DEFAULT true,`encrypted_url` text NOT NULL DEFAULT "",`refresh_interval_seconds` integer NOT NULL DEFAULT 900,`default_account_capacity` integer NOT NULL DEFAULT 0,`last_synced_at` datetime,`next_sync_at` datetime,`last_sync_imported` integer NOT NULL DEFAULT 0,`last_sync_error` text NOT NULL DEFAULT "",`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`encrypted_proxy_url` text NOT NULL DEFAULT "",CONSTRAINT `chk_egress_subscription_sources_refresh` CHECK (refresh_interval_seconds BETWEEN 60 AND 86400),CONSTRAINT `chk_egress_subscription_sources_imported` CHECK (last_sync_imported >= 0),CONSTRAINT `chk_egress_subscription_sources_capacity` CHECK (default_account_capacity BETWEEN 0 AND 100000),CONSTRAINT `chk_egress_subscription_sources_error` CHECK (length(last_sync_error) <= 512),CONSTRAINT `chk_egress_subscription_sources_name` CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT `chk_egress_subscription_sources_url` CHECK (length(encrypted_url) <= 65536),CONSTRAINT `chk_egress_subscription_sources_scope` CHECK (scope IN ('grok_build','grok_web','grok_console','grok_web_asset','grok_console_asset')),CONSTRAINT `chk_egress_subscription_sources_proxy_url` CHECK (length(encrypted_proxy_url) <= 65536));
CREATE TABLE IF NOT EXISTS "model_routes"  (`id` integer PRIMARY KEY AUTOINCREMENT,`public_id` text NOT NULL,`provider` text NOT NULL,`upstream_model` text NOT NULL,`capability` text NOT NULL,`origin` text NOT NULL DEFAULT "discovered",`enabled` numeric NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `chk_model_routes_public_id` CHECK (length(trim(public_id)) BETWEEN 1 AND 255),CONSTRAINT `chk_model_routes_provider` CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT `chk_model_routes_upstream_model` CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255),CONSTRAINT `chk_model_routes_origin` CHECK (origin IN ('catalog','discovered','manual')),CONSTRAINT `chk_model_routes_capability` CHECK (capability IN ('responses','chat','image','image_edit','video','tts','stt','realtime')));
CREATE TABLE `egress_proxy_profiles` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`encrypted_proxy_url` text NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `chk_egress_proxy_profiles_name` CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT `chk_egress_proxy_profiles_url` CHECK (length(encrypted_proxy_url) BETWEEN 1 AND 65536));
CREATE TABLE IF NOT EXISTS "egress_nodes"  (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`scope` text NOT NULL,`enabled` numeric NOT NULL DEFAULT true,`encrypted_proxy_url` text NOT NULL DEFAULT "",`user_agent` text NOT NULL DEFAULT "",`encrypted_cloudflare_cookie` text NOT NULL DEFAULT "",`health` real NOT NULL DEFAULT 1,`failure_count` integer NOT NULL DEFAULT 0,`cooldown_until` datetime,`last_error` text,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`proxy_pool` numeric NOT NULL DEFAULT false,`source_id` integer,`source_key` text NOT NULL DEFAULT "",`account_capacity` integer NOT NULL DEFAULT 0,`clearance_refreshed_at` datetime,`clearance_fingerprint` text NOT NULL DEFAULT "",`clearance_binding_fingerprint` text NOT NULL DEFAULT "",`probe_status` text NOT NULL DEFAULT "unknown",`last_probed_at` datetime,`probe_latency_ms` integer NOT NULL DEFAULT 0,`exit_ip` text NOT NULL DEFAULT "",`probe_error` text NOT NULL DEFAULT "",`probe_provider` text NOT NULL DEFAULT "",`ipv4_probe_status` text NOT NULL DEFAULT "unknown",`ipv4_last_probed_at` datetime,`ipv4_probe_latency_ms` integer NOT NULL DEFAULT 0,`ipv4_exit_ip` text NOT NULL DEFAULT "",`ipv4_probe_error` text NOT NULL DEFAULT "",`ipv6_probe_status` text NOT NULL DEFAULT "unknown",`ipv6_last_probed_at` datetime,`ipv6_probe_latency_ms` integer NOT NULL DEFAULT 0,`ipv6_exit_ip` text NOT NULL DEFAULT "",`ipv6_probe_error` text NOT NULL DEFAULT "",`proxy_profile_id` integer,CONSTRAINT `chk_egress_nodes_proxy_url` CHECK (length(encrypted_proxy_url) <= 65536),CONSTRAINT `chk_egress_nodes_health` CHECK (health >= 0 AND health <= 1),CONSTRAINT `chk_egress_nodes_failures` CHECK (failure_count >= 0),CONSTRAINT `chk_egress_nodes_name` CHECK (length(trim(name)) BETWEEN 1 AND 160),CONSTRAINT `chk_egress_nodes_user_agent` CHECK (length(user_agent) <= 512),CONSTRAINT `chk_egress_nodes_cf_cookie` CHECK (length(encrypted_cloudflare_cookie) <= 65536),CONSTRAINT `chk_egress_nodes_last_error` CHECK (length(last_error) <= 512),CONSTRAINT `fk_egress_nodes_source` FOREIGN KEY (`source_id`) REFERENCES `egress_subscription_sources`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT `chk_egress_nodes_ipv6_exit_ip` CHECK (length(ipv6_exit_ip) <= 64),CONSTRAINT `chk_egress_nodes_ipv4_exit_ip` CHECK (length(ipv4_exit_ip) <= 64),CONSTRAINT `chk_egress_nodes_ipv6_probe_status` CHECK (ipv6_probe_status IN ('unknown','healthy','unhealthy')),CONSTRAINT `chk_egress_nodes_ipv6_probe_latency` CHECK (ipv6_probe_latency_ms >= 0),CONSTRAINT `chk_egress_nodes_ipv4_probe_latency` CHECK (ipv4_probe_latency_ms >= 0),CONSTRAINT `chk_egress_nodes_probe_error` CHECK (length(probe_error) <= 512),CONSTRAINT `chk_egress_nodes_probe_provider` CHECK (probe_provider IN ('','ipinfo','cloudflare')),CONSTRAINT `chk_egress_nodes_ipv4_probe_status` CHECK (ipv4_probe_status IN ('unknown','healthy','unhealthy')),CONSTRAINT `chk_egress_nodes_exit_ip` CHECK (length(exit_ip) <= 64),CONSTRAINT `chk_egress_nodes_ipv6_probe_error` CHECK (length(ipv6_probe_error) <= 512),CONSTRAINT `chk_egress_nodes_probe_status` CHECK (probe_status IN ('unknown','healthy','unhealthy')),CONSTRAINT `chk_egress_nodes_source_key` CHECK (length(source_key) <= 64),CONSTRAINT `chk_egress_nodes_ipv4_probe_error` CHECK (length(ipv4_probe_error) <= 512),CONSTRAINT `chk_egress_nodes_clearance_fingerprint` CHECK (length(clearance_fingerprint) IN (0, 64)),CONSTRAINT `chk_egress_nodes_capacity` CHECK (account_capacity BETWEEN 0 AND 100000),CONSTRAINT `chk_egress_nodes_probe_latency` CHECK (probe_latency_ms >= 0),CONSTRAINT `chk_egress_nodes_clearance_binding_fingerprint` CHECK (length(clearance_binding_fingerprint) IN (0, 64)),CONSTRAINT `chk_egress_nodes_specific_scope` CHECK (scope IN ('grok_build','grok_web','grok_console','grok_web_asset','grok_console_asset')),CONSTRAINT `fk_egress_nodes_proxy_profile` FOREIGN KEY (`proxy_profile_id`) REFERENCES `egress_proxy_profiles`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "account_credentials"  (`account_id` integer PRIMARY KEY AUTOINCREMENT,`auth_type` text NOT NULL,`client_id` text,`encrypted_primary` text NOT NULL DEFAULT "",`encrypted_refresh` text NOT NULL DEFAULT "",`expires_at` datetime,`refresh_due_at` datetime,`last_refresh_at` datetime,`refresh_failures` integer NOT NULL DEFAULT 0,`last_refresh_error` text NOT NULL DEFAULT "",`updated_at` datetime NOT NULL,`encrypted_cloudflare_cookie` text NOT NULL DEFAULT "",`last_refresh_error_status` integer NOT NULL DEFAULT 0,`last_refresh_error_message` text NOT NULL DEFAULT "",`last_refresh_error_response` text NOT NULL DEFAULT "",`refresh_permanent` numeric NOT NULL DEFAULT false,`build_bot_flag_source` integer NOT NULL DEFAULT 0,`refresh_unclassified_auth_failures` integer NOT NULL DEFAULT 0,CONSTRAINT `fk_provider_accounts_credential` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `chk_account_credentials_refresh_error` CHECK (length(last_refresh_error) <= 100),CONSTRAINT `chk_account_credentials_auth_type` CHECK (auth_type IN ('oauth','sso')),CONSTRAINT `chk_account_credentials_client_id` CHECK (length(client_id) <= 255),CONSTRAINT `chk_account_credentials_secret` CHECK (((auth_type = 'oauth' AND (encrypted_primary <> '' OR encrypted_refresh <> '')) OR (auth_type = 'sso' AND encrypted_primary <> '' AND encrypted_refresh = '')) AND length(encrypted_primary) <= 65536 AND length(encrypted_refresh) <= 65536),CONSTRAINT `chk_account_credentials_refresh_failures` CHECK (refresh_failures >= 0),CONSTRAINT `chk_account_credentials_refresh_error_message` CHECK (length(last_refresh_error_message) <= 512),CONSTRAINT `chk_account_credentials_refresh_error_response` CHECK (length(last_refresh_error_response) <= 4096),CONSTRAINT `chk_account_credentials_cf_cookie` CHECK (length(encrypted_cloudflare_cookie) <= 65536),CONSTRAINT `chk_account_credentials_refresh_error_status` CHECK (last_refresh_error_status >= 0),CONSTRAINT `chk_account_credentials_build_bot_flag_source` CHECK (build_bot_flag_source IN (0,1,2)),CONSTRAINT `chk_account_credentials_refresh_unclassified_auth_failures` CHECK (refresh_unclassified_auth_failures >= 0));
