CREATE TABLE IF NOT EXISTS "request_audits"  (`id` integer PRIMARY KEY AUTOINCREMENT,`event_id` text,`request_id` text NOT NULL,`client_key_id` integer NOT NULL,`client_key_name` text,`model_route_id` integer NOT NULL,`model_public_id` text,`model_upstream_model` text,`provider` text NOT NULL,`operation` text NOT NULL,`usage_source` text NOT NULL,`account_id` integer,`account_name` text,`status_code` integer NOT NULL,`streaming` numeric NOT NULL DEFAULT false,`media_input_images` integer NOT NULL DEFAULT 0,`media_output_images` integer NOT NULL DEFAULT 0,`media_output_seconds` integer NOT NULL DEFAULT 0,`input_tokens` integer NOT NULL DEFAULT 0,`cached_input_tokens` integer NOT NULL DEFAULT 0,`output_tokens` integer NOT NULL DEFAULT 0,`reasoning_tokens` integer NOT NULL DEFAULT 0,`total_tokens` integer NOT NULL DEFAULT 0,`cost_in_usd_ticks` integer NOT NULL DEFAULT 0,`estimated_cost_in_usd_ticks` integer NOT NULL DEFAULT 0,`pricing_model` text,`pricing_version` text,`num_sources_used` integer NOT NULL DEFAULT 0,`num_server_side_tools_used` integer NOT NULL DEFAULT 0,`context_input_tokens` integer NOT NULL DEFAULT 0,`context_output_tokens` integer NOT NULL DEFAULT 0,`duration_ms` integer NOT NULL DEFAULT 0,`error_code` text,`created_at` datetime NOT NULL,`egress_node_id` integer,`egress_node_name` text NOT NULL DEFAULT "",`egress_scope` text NOT NULL DEFAULT "",`egress_mode` text NOT NULL DEFAULT "",`first_token_ms` integer,`attempt_count` integer NOT NULL DEFAULT 0,`client_ip` text NOT NULL DEFAULT "",`reasoning_effort` text NOT NULL DEFAULT "",`request_method` text NOT NULL DEFAULT "",`request_path` text NOT NULL DEFAULT "",`request_headers_json` text NOT NULL DEFAULT "{}",CONSTRAINT `chk_request_audits_pricing_model` CHECK (length(pricing_model) <= 100),CONSTRAINT `chk_request_audits_event_id` CHECK (event_id = '' OR length(event_id) BETWEEN 16 AND 64),CONSTRAINT `chk_request_audits_model_upstream_model` CHECK (length(model_upstream_model) <= 255),CONSTRAINT `chk_request_audits_provider` CHECK (provider IN ('grok_build','grok_web','grok_console')),CONSTRAINT `chk_request_audits_error_code` CHECK (length(error_code) <= 100),CONSTRAINT `chk_request_audits_client_key_name` CHECK (length(client_key_name) <= 160),CONSTRAINT `chk_request_audits_pricing_version` CHECK (length(pricing_version) <= 20),CONSTRAINT `chk_request_audits_account_id` CHECK (account_id IS NULL OR account_id > 0),CONSTRAINT `chk_request_audits_usage_source` CHECK (usage_source IN ('upstream','estimated','none')),CONSTRAINT `chk_request_audits_status_code` CHECK (status_code BETWEEN 100 AND 599),CONSTRAINT `chk_request_audits_account_name` CHECK (length(account_name) <= 160),CONSTRAINT `chk_request_audits_client_key_id` CHECK (client_key_id > 0),CONSTRAINT `chk_request_audits_model_public_id` CHECK (length(model_public_id) <= 255),CONSTRAINT `chk_request_audits_model_route_id` CHECK (model_route_id > 0),CONSTRAINT `chk_request_audits_request_id` CHECK (length(request_id) BETWEEN 1 AND 64),CONSTRAINT `chk_request_audits_metrics` CHECK (media_input_images >= 0 AND media_output_images >= 0 AND media_output_seconds >= 0 AND input_tokens >= 0 AND cached_input_tokens >= 0 AND output_tokens >= 0 AND reasoning_tokens >= 0 AND total_tokens >= 0 AND cost_in_usd_ticks >= 0 AND estimated_cost_in_usd_ticks >= 0 AND num_sources_used >= 0 AND num_server_side_tools_used >= 0 AND context_input_tokens >= 0 AND context_output_tokens >= 0 AND duration_ms >= 0),CONSTRAINT `chk_request_audits_egress_node_name` CHECK (length(egress_node_name) <= 160),CONSTRAINT `chk_request_audits_attempt_count` CHECK (attempt_count >= 0),CONSTRAINT `chk_request_audits_egress_mode` CHECK (egress_mode IN ('','direct','proxy')),CONSTRAINT `chk_request_audits_egress_node_id` CHECK (egress_node_id IS NULL OR egress_node_id > 0),CONSTRAINT `chk_request_audits_egress_scope` CHECK (egress_scope IN ('','grok_build','grok_web','grok_console','grok_web_asset','grok_console_asset')),CONSTRAINT `chk_request_audits_operation` CHECK (operation IN ('responses','compaction','chat','messages','image','image_edit','video','tts','stt','realtime','voice')),CONSTRAINT `chk_request_audits_reasoning_effort` CHECK (length(reasoning_effort) <= 32),CONSTRAINT `chk_request_audits_request_path` CHECK (length(request_path) <= 2048),CONSTRAINT `chk_request_audits_client_ip` CHECK (length(client_ip) <= 45),CONSTRAINT `chk_request_audits_request_method` CHECK (length(request_method) <= 16),CONSTRAINT `chk_request_audits_request_headers` CHECK (length(request_headers_json) <= 65536));
CREATE TABLE IF NOT EXISTS "media_jobs"  (`id` text,`request_id` text NOT NULL,`client_key_id` integer NOT NULL,`client_key_name` text NOT NULL DEFAULT "",`account_id` integer,`account_name` text NOT NULL DEFAULT "",`provider` text NOT NULL,`model` text NOT NULL,`model_route_id` integer NOT NULL,`upstream_model` text NOT NULL,`prompt` text NOT NULL,`seconds` integer NOT NULL,`size` text NOT NULL DEFAULT "",`quality` text NOT NULL DEFAULT "",`status` text NOT NULL,`progress` integer NOT NULL,`input_json` text NOT NULL DEFAULT "{}",`upstream_url` text NOT NULL DEFAULT "",`content_type` text NOT NULL DEFAULT "",`error_code` text NOT NULL DEFAULT "",`error_message` text NOT NULL DEFAULT "",`lease_until` datetime,`claim_token` text NOT NULL DEFAULT "",`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,`completed_at` datetime,`usage_recorded_at` datetime,`egress_node_id` integer,`egress_node_name` text NOT NULL DEFAULT "",`egress_scope` text NOT NULL DEFAULT "",`egress_mode` text NOT NULL DEFAULT "",`input_image_count` integer,`result_asset_id` text NOT NULL DEFAULT "",`operation` text NOT NULL DEFAULT "generate",`client_ip` text NOT NULL DEFAULT "",PRIMARY KEY (`id`),CONSTRAINT `fk_media_jobs_client_key` FOREIGN KEY (`client_key_id`) REFERENCES `client_keys`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `chk_media_jobs_model_route_id` CHECK (model_route_id > 0),CONSTRAINT `chk_media_jobs_status` CHECK (status IN ('queued','in_progress','completed','failed')),CONSTRAINT `chk_media_jobs_content_type` CHECK (length(content_type) <= 128),CONSTRAINT `chk_media_jobs_error_message` CHECK (length(error_message) <= 512),CONSTRAINT `chk_media_jobs_prompt` CHECK (length(prompt) BETWEEN 0 AND 100000),CONSTRAINT `chk_media_jobs_upstream_model` CHECK (length(trim(upstream_model)) BETWEEN 1 AND 255),CONSTRAINT `chk_media_jobs_progress` CHECK (progress BETWEEN 0 AND 100),CONSTRAINT `chk_media_jobs_claim_token` CHECK (claim_token = '' OR length(claim_token) BETWEEN 16 AND 64),CONSTRAINT `chk_media_jobs_client_key_id` CHECK (client_key_id > 0),CONSTRAINT `chk_media_jobs_id` CHECK (length(id) BETWEEN 1 AND 64),CONSTRAINT `chk_media_jobs_request_id` CHECK (length(request_id) BETWEEN 1 AND 64),CONSTRAINT `chk_media_jobs_client_key_name` CHECK (length(client_key_name) <= 160),CONSTRAINT `chk_media_jobs_account_id` CHECK (account_id > 0),CONSTRAINT `chk_media_jobs_upstream_url` CHECK (length(upstream_url) <= 8192),CONSTRAINT `chk_media_jobs_error_code` CHECK (length(error_code) <= 100),CONSTRAINT `chk_media_jobs_account_name` CHECK (length(account_name) <= 160),CONSTRAINT `chk_media_jobs_model` CHECK (length(trim(model)) BETWEEN 1 AND 255),CONSTRAINT `chk_media_jobs_input_image_count` CHECK (input_image_count IS NULL OR input_image_count BETWEEN 0 AND 8),CONSTRAINT `chk_media_jobs_egress_mode` CHECK (egress_mode IN ('','direct','proxy')),CONSTRAINT `chk_media_jobs_egress_node_id` CHECK (egress_node_id IS NULL OR egress_node_id > 0),CONSTRAINT `chk_media_jobs_result_asset_id` CHECK (result_asset_id = '' OR length(trim(result_asset_id)) BETWEEN 16 AND 64),CONSTRAINT `chk_media_jobs_egress_node_name` CHECK (length(egress_node_name) <= 160),CONSTRAINT `chk_media_jobs_input_json` CHECK (length(input_json) <= 33554432),CONSTRAINT `fk_media_jobs_account` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT `chk_media_jobs_provider` CHECK (provider IN ('grok_web','grok_build','grok_console')),CONSTRAINT `chk_media_jobs_egress_scope` CHECK (egress_scope IN ('','grok_web','grok_build','grok_console')),CONSTRAINT `chk_media_jobs_operation` CHECK (operation IN ('generate','edit','extend')),CONSTRAINT `chk_media_jobs_seconds` CHECK (seconds BETWEEN 0 AND 15),CONSTRAINT `chk_media_jobs_size` CHECK (length(trim(size)) BETWEEN 0 AND 32),CONSTRAINT `chk_media_jobs_quality` CHECK (length(trim(quality)) BETWEEN 0 AND 32),CONSTRAINT `chk_media_jobs_client_ip` CHECK (length(client_ip) <= 45));
