CREATE TRIGGER trg_egress_nodes_unhealthy
AFTER UPDATE OF probe_status ON egress_nodes
WHEN NEW.probe_status != 'healthy' AND NEW.enabled = 1
BEGIN
    UPDATE egress_nodes SET enabled = 0 WHERE id = NEW.id;
END;
CREATE TRIGGER trg_egress_nodes_healthy
AFTER UPDATE OF probe_status ON egress_nodes
WHEN NEW.probe_status = 'healthy' AND NEW.enabled = 0
BEGIN
    UPDATE egress_nodes SET enabled = 1 WHERE id = NEW.id;
END;
